// c14_int8_dot_requant_regs.sv: the shell window of course task c14_int8_dot_requant.
module c14_int8_dot_requant_regs (
    input  logic        clk,
    input  logic        rst,
    output logic [15:0] led,
    input  logic [6:0]  win_addr,
    input  logic        win_wr,
    input  logic        win_rd,
    input  logic [31:0] win_wdata,
    output logic [31:0] win_rdata
);
    logic [63:0]        a_r, w_r;
    logic [31:0]        bias_r, acc;
    logic [15:0]        mult_r;
    logic [4:0]         shift_r;
    logic               relu_r, go, ov, vld;
    logic signed [7:0]  y;
    logic [31:0]        acc_s;

    assign led = {15'd0, vld};

    dot_requant #(.N(8)) u_core (.clk(clk), .rst_n(!rst), .in_valid(go), .a(a_r), .w(w_r), .bias(bias_r),
                                 .mult(mult_r), .shift(shift_r), .relu(relu_r), .out_valid(ov), .y(y), .acc(acc_s));

    always_ff @(posedge clk) begin
        go <= 1'b0;
        if (ov) vld <= 1'b1;
        if (win_wr) begin
            case (win_addr)
                7'd0: a_r[31:0]   <= win_wdata;
                7'd1: a_r[63:32]  <= win_wdata;
                7'd2: w_r[31:0]   <= win_wdata;
                7'd3: w_r[63:32]  <= win_wdata;
                7'd4: bias_r      <= win_wdata;
                7'd5: mult_r      <= win_wdata[15:0];
                7'd6: begin shift_r <= win_wdata[4:0]; relu_r <= win_wdata[8]; end
                7'd7: begin go <= 1'b1; vld <= 1'b0; end
                default: ;
            endcase
        end
        win_rdata <= 32'd0;
        if (win_rd) begin
            case (win_addr)
                7'd0:  win_rdata <= a_r[31:0];
                7'd1:  win_rdata <= a_r[63:32];
                7'd2:  win_rdata <= w_r[31:0];
                7'd3:  win_rdata <= w_r[63:32];
                7'd4:  win_rdata <= bias_r;
                7'd5:  win_rdata <= {16'd0, mult_r};
                7'd6:  win_rdata <= {23'd0, relu_r, 3'd0, shift_r};
                7'd8:  win_rdata <= vld ? {24'd0, y} : 32'd0;
                7'd9:  win_rdata <= vld ? acc_s : 32'd0;
                7'd10: win_rdata <= {31'd0, vld};
                default: ;
            endcase
        end
        if (rst) begin
            a_r <= '0; w_r <= '0; bias_r <= '0; mult_r <= '0; shift_r <= 5'd1; relu_r <= 1'b0;
            go <= 1'b0; vld <= 1'b0; win_rdata <= 32'd0;
        end
    end
endmodule

// c14_int8_dot_requant_top.sv: board top (Nexys A7-100T, master-XDC port names), test shell DESIGN_ID "DOTQ".
// Reference design for course task c14_int8_dot_requant; the shell window is wired to c14_int8_dot_requant_regs.
module c14_int8_dot_requant_top #(
    parameter int          CLKS_PER_BIT   = 868,
    parameter int          TIMEOUT_CYCLES = 100_000,
    parameter logic [31:0] BUILD_STAMP    = 32'h0
) (
    input  logic        CLK100MHZ,
    input  logic        CPU_RESETN,
    output logic [15:0] LED,
    input  logic        UART_TXD_IN,
    output logic        UART_RXD_OUT
);
    logic        clk, rst, win_wr, win_rd;
    logic [6:0]  win_addr;
    logic [31:0] win_wdata, win_rdata;

    assign clk = CLK100MHZ;
    reset_sync u_rst (.clk(clk), .rst_n_async(CPU_RESETN), .rst(rst));

    fpga_shell #(.CLKS_PER_BIT(CLKS_PER_BIT), .TIMEOUT_CYCLES(TIMEOUT_CYCLES),
                 .DESIGN_ID(32'h444f5451), .BUILD_STAMP(BUILD_STAMP)) u_shell (
        .clk(clk), .rst(rst), .uart_rx(UART_TXD_IN), .uart_tx(UART_RXD_OUT),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));

    c14_int8_dot_requant_regs u_regs (
        .clk(clk), .rst(rst), .led(LED),
        .win_addr(win_addr), .win_wr(win_wr), .win_rd(win_rd), .win_wdata(win_wdata), .win_rdata(win_rdata));
endmodule

// Part 14 lesson 3 exercise: an int8 dot-product unit with requantisation and saturation (the core of one output of a quantised layer).
//
// N pairs of signed 8-bit numbers a[i] (activations) and w[i] (weights), packed a[i*8 +: 8], w[i*8 +: 8]. With in_valid high, one clock later (out_valid high, one clock
// of latency, rst_n clears out_valid only; synchronous, active low):
//   acc = sum(a[i] * w[i]) + bias                      (bias: signed 32 bit; the sum fits 32 bits for N up to 4096)
//   r   = (acc * mult + 2^(shift-1)) >>> shift         (mult: UNSIGNED 16 bit; shift: 1 .. 31; 64-bit signed product; >>> is the arithmetic (floor) shift)
//   y   = clamp(r, lo, 127)   with lo = 0 when relu = 1 and -128 when relu = 0
// Outputs: y (signed 8 bit) and acc (the signed 32-bit accumulator including the bias). Same ordering rule as the golden model tools/ml_models.requant.
module dot_requant #(
    parameter int N = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  in_valid,
    input  logic [N*8-1:0]        a,
    input  logic [N*8-1:0]        w,
    input  logic signed [31:0]    bias,
    input  logic [15:0]           mult,
    input  logic [4:0]            shift,
    input  logic                  relu,
    output logic                  out_valid,
    output logic signed [7:0]     y,
    output logic signed [31:0]    acc
);
    logic signed [31:0] s;
    logic signed [63:0] p, r;
    logic signed [63:0] rnd;
    always_comb begin
        s = bias;
        for (int i = 0; i < N; i++) s = s + $signed(a[i*8 +: 8]) * $signed(w[i*8 +: 8]);
        p = s * $signed({1'b0, mult});
        rnd = 64'sd1 <<< (shift - 5'd1);
        r = (p + rnd) >>> shift;
    end
    always_ff @(posedge clk) begin
        if (!rst_n) out_valid <= 1'b0;
        else out_valid <= in_valid;
        if (in_valid) begin
            acc <= s;
            if (r > 64'sd127) y <= 8'sd127;
            else if (r < (relu ? 64'sd0 : -64'sd128)) y <= relu ? 8'sd0 : -8'sd128;
            else y <= r[7:0];
        end
    end
endmodule
